"""Matched warm-cache, fresh-process compiler comparison. Local contended diagnostic only."""
import hashlib, importlib.util, json, os, pathlib, platform, random, resource, statistics, subprocess, time
ROOT = pathlib.Path('/home/jeremy/justrust-clean-room')
OUT = pathlib.Path('/home/jeremy/.jcode/scratch/frontend-opt-20261030')
BINS = {k: OUT / (k + '-jr-rust') for k in ('baseline', 'candidate')}
sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()
spec = importlib.util.spec_from_file_location('fixtures', ROOT / 'experiments/compiler.py')
fixtures = importlib.util.module_from_spec(spec); spec.loader.exec_module(fixtures)
sources = {'functions4': fixtures.module_source_for(4), 'functions256': fixtures.module_source_for(256), 'mandelbrot': (ROOT / 'experiments/programs/mandelbrot.rs').read_text()}
report = {'schema': 1, 'scope': 'focused fixtures, not a general Rust compile speed claim', 'conditions': {'repeats': 7, 'workers': [1, 8], 'cache': 'warm filesystem, fresh process, no link-cache opt-in', 'host': platform.platform(), 'affinity': sorted(os.sched_getaffinity(0)), 'topology': subprocess.check_output(['lscpu'], text=True), 'rustc': subprocess.check_output(['rustc', '-Vv'], text=True), 'load_start': os.getloadavg(), 'timing': 'process wall and process user+system CPU, execution validation outside timing, no profile serialization'}, 'binaries': {k: {'sha256': sha(p), 'bytes': p.stat().st_size} for k, p in BINS.items()}, 'sources': sources, 'samples': [], 'summary': [], 'runner': pathlib.Path(__file__).read_text()}
# Capture all release-source identities. Baseline snapshot remains in source/;
# optimized-files/ holds the only two candidate replacements at the same path.
manifest = {}
for path in sorted((OUT / 'source').rglob('*')):
 if path.is_file() and 'target' not in path.relative_to(OUT / 'source').parts and path.suffix in ('.rs', '.toml', '.lock', '.json'):
  manifest[str(path.relative_to(OUT / 'source'))] = sha(path)
report['baseline_source_manifest'] = manifest
report['candidate_replacements'] = {str(pathlib.Path('src/compiler') / p.name): sha(p) for p in sorted((OUT / 'optimized-files').glob('*.rs'))}
env = dict(os.environ, JR_OPT='off')
def invoke(args):
 before = resource.getrusage(resource.RUSAGE_CHILDREN); start = time.perf_counter_ns()
 p = subprocess.run(args, capture_output=True, timeout=120, env=env)
 wall = time.perf_counter_ns() - start; after = resource.getrusage(resource.RUSAGE_CHILDREN)
 if p.returncode: raise RuntimeError(f'{args}: {p.returncode}\n{p.stdout.decode()}\n{p.stderr.decode()}')
 cpu = (after.ru_utime + after.ru_stime - before.ru_utime - before.ru_stime) * 1e9
 return p, wall, cpu
with (OUT / 'paired-samples.jsonl').open('x') as log:
 for name, text in sources.items():
  directory = OUT / 'inputs' / name; directory.mkdir(parents=True, exist_ok=False)
