  expected = subprocess.check_output([str(reference)], timeout=30)
  for tool, binary in BINS.items():
   for workers in [1, 8]: invoke([str(binary), str(source), '--check', '--workers', str(workers)])
  for repeat in range(7):
   cells = [(w, m) for w in [1, 8] for m in ['check', 'build']]
   random.Random(17000 + repeat).shuffle(cells)
   for workers, mode in cells:
    order = list(BINS) if repeat % 2 == 0 else list(BINS)[::-1]
    for tool in order:
     artifact = OUT / f'{name}-{mode}-{workers}-{repeat}-{tool}.elf'
     args = [str(BINS[tool]), str(source), '--workers', str(workers)] + (['--check'] if mode == 'check' else ['-o', str(artifact)])
     p, wall, cpu = invoke(args); summary = json.loads(p.stdout)
     assert not summary['failures'] and summary['capture_complete'] and not summary['events_dropped'], summary
     if mode == 'build':
      actual = subprocess.check_output([str(artifact)], timeout=30)
      assert actual == expected, (name, tool, actual, expected)
      artifact.unlink()
     row = {'workload': name, 'mode': mode, 'workers': workers, 'tool': tool, 'repeat': repeat, 'wall_ns': wall, 'cpu_ns': cpu, 'cpu_concurrency': cpu / wall, 'compiler': summary, 'source_sha256': sha(source), 'load': os.getloadavg()}
     report['samples'].append(row); log.write(json.dumps(row) + '\n'); log.flush()
   print(f'{name}: paired repetition {repeat + 1}/7', flush=True)
for name in sources:
 for mode in ['check', 'build']:
  for workers in [1, 8]:
   groups = {k: [r for r in report['samples'] if (r['workload'], r['mode'], r['workers'], r['tool']) == (name, mode, workers, k)] for k in BINS}
   item = {'workload': name, 'mode': mode, 'workers': workers}
   for tool, values in groups.items():
    item[tool] = {'median_ms': statistics.median(r['wall_ns'] for r in values) / 1e6, 'min_ms': min(r['wall_ns'] for r in values) / 1e6, 'max_ms': max(r['wall_ns'] for r in values) / 1e6, 'cpu_ms': statistics.median(r['cpu_ns'] for r in values) / 1e6, 'cpu_concurrency': statistics.median(r['cpu_concurrency'] for r in values)}
   item['median_paired_after_before'] = statistics.median(a['wall_ns'] / b['wall_ns'] for a, b in zip(groups['candidate'], groups['baseline']))
   item['median_wall_reduction_percent'] = 100 * (1 - item['candidate']['median_ms'] / item['baseline']['median_ms'])
   report['summary'].append(item)
report['conditions']['load_end'] = os.getloadavg()
(OUT / 'paired-results.json').write_text(json.dumps(report, indent=2) + '\n')
